Tool: find_scheduled_appointments
Description: Find Scheduled Appointments
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "description": "ID of the patient",
          "title": "Patient Id"
        },
        "doctor_id": {
          "type": "integer",
          "description": "ID of the doctor",
          "title": "Doctor Id"
        },
        "date": {
          "type": "string",
          "description": "Date of the appointment in YYYY-MM-DD format",
          "title": "Date"
