Tool response:
Tool: add_to_waitlist
Description: Add To Waitlist
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "doctor_id": {
          "type": "integer",
          "title": "Doctor Id"
        },
